using System.Drawing;using System.Windows.Forms;
namespace LSE.InventorFootprintTools;
public sealed class SettingsForm:Form{
 readonly AppSettings s=SettingsService.Load();readonly Dictionary<string,TextBox> boxes=new();readonly Dictionary<string,CheckBox> checks=new();
 public SettingsForm(){Text="LSE Footprint Tools Settings";StartPosition=FormStartPosition.CenterParent;Size=new Size(980,720);var p=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,Padding=new Padding(12),AutoScroll=true};p.ColumnStyles.Add(new(SizeType.Absolute,240));p.ColumnStyles.Add(new(SizeType.Percent,100));p.ColumnStyles.Add(new(SizeType.Absolute,100));int r=0;
  Add(p,"Catalog MDB (default_cat.mdb)",nameof(s.CatalogPath),s.CatalogPath,r++,"Access (*.mdb)|*.mdb");Add(p,"Footprint lookup MDB",nameof(s.FootprintLookupPath),s.FootprintLookupPath,r++,"Access (*.mdb;*.accdb)|*.mdb;*.accdb");Add(p,"Footprint library folder",nameof(s.FootprintLibraryFolder),s.FootprintLibraryFolder,r++,"folder");Add(p,"Naming standard JSON",nameof(s.NamingStandardPath),s.NamingStandardPath,r++,"JSON (*.json)|*.json");Add(p,"Inventor drawing template (blank = default)",nameof(s.DrawingTemplatePath),s.DrawingTemplatePath,r++,"Inventor drawing (*.idw;*.dwg)|*.idw;*.dwg");
  Add(p,"Footprint units (in or mm)",nameof(s.FootprintUnits),s.FootprintUnits,r++);Add(p,"Geometry layer",nameof(s.GeometryLayer),s.GeometryLayer,r++);Add(p,"Attribute layer",nameof(s.AttributeLayer),s.AttributeLayer,r++);Add(p,"Tag text height (in)",nameof(s.TagTextHeight),Inv(s.TagTextHeight),r++);Add(p,"Curve tolerance (footprint units)",nameof(s.CurveTolerance),Inv(s.CurveTolerance),r++);Add(p,"Max curve segments per view",nameof(s.MaxCurves),s.MaxCurves.ToString(),r++);Add(p,"LSE part attribute on footprint",nameof(s.LsePartAttribute),s.LsePartAttribute,r++);
  AddCheck(p,"Convert DXF to DWG with AutoCAD",nameof(s.ConvertToDwgWithAutoCad),s.ConvertToDwgWithAutoCad,r++);AddCheck(p,"Append \", MPN <catalog>\" to DESCRIPTION",nameof(s.AppendMpnToDescription),s.AppendMpnToDescription,r++);
  Add(p,"Vault Explorer folder (auto-discovered when blank)",nameof(s.VaultExplorerPath),s.VaultExplorerPath,r++,"folder");Add(p,"Vault server",nameof(s.VaultServer),s.VaultServer,r++);Add(p,"Vault name",nameof(s.VaultName),s.VaultName,r++);Add(p,"Catalog Vault path ($/folder/.../default_cat.mdb; blank = no Vault)",nameof(s.CatalogVaultPath),s.CatalogVaultPath,r++);
  var info=new Label{Text="Settings file: "+SettingsService.SettingsPath,AutoSize=true,Anchor=AnchorStyles.Left};p.Controls.Add(info,0,r);p.SetColumnSpan(info,2);var test=new Button{Text="Test",Dock=DockStyle.Fill};test.Click+=(_,_)=>Test();p.Controls.Add(test,2,r++);p.RowStyles.Add(new(SizeType.Absolute,48));var save=new Button{Text="Save",Dock=DockStyle.Fill};save.Click+=(_,_)=>Save();p.Controls.Add(save,2,r);p.RowStyles.Add(new(SizeType.Absolute,48));Controls.Add(p);}
 void Add(TableLayoutPanel p,string label,string key,string value,int row,string? browse=null){p.Controls.Add(new Label{Text=label,AutoSize=true,Anchor=AnchorStyles.Left},0,row);var t=new TextBox{Text=value,Dock=DockStyle.Fill};boxes[key]=t;p.Controls.Add(t,1,row);if(browse is not null){var b=new Button{Text="Browse",Dock=DockStyle.Fill};b.Click+=(_,_)=>{if(browse=="folder"){using var f=new FolderBrowserDialog();if(f.ShowDialog(this)==DialogResult.OK)t.Text=f.SelectedPath;}else{using var f=new OpenFileDialog{Filter=browse,CheckFileExists=false};if(f.ShowDialog(this)==DialogResult.OK)t.Text=f.FileName;}};p.Controls.Add(b,2,row);}p.RowStyles.Add(new(SizeType.Absolute,42));}
 void AddCheck(TableLayoutPanel p,string label,string key,bool value,int row){p.Controls.Add(new Label{Text=label,AutoSize=true,Anchor=AnchorStyles.Left},0,row);var c=new CheckBox{Checked=value,Anchor=AnchorStyles.Left,AutoSize=true};checks[key]=c;p.Controls.Add(c,1,row);p.RowStyles.Add(new(SizeType.Absolute,36));}
 void Save(){try{s.CatalogPath=boxes[nameof(s.CatalogPath)].Text.Trim();s.FootprintLookupPath=boxes[nameof(s.FootprintLookupPath)].Text.Trim();s.FootprintLibraryFolder=boxes[nameof(s.FootprintLibraryFolder)].Text.Trim();s.NamingStandardPath=boxes[nameof(s.NamingStandardPath)].Text.Trim();s.DrawingTemplatePath=boxes[nameof(s.DrawingTemplatePath)].Text.Trim();
  string units=boxes[nameof(s.FootprintUnits)].Text.Trim().ToLowerInvariant();if(units!="in"&&units!="mm")throw new InvalidOperationException("Footprint units must be 'in' or 'mm'.");s.FootprintUnits=units;s.GeometryLayer=boxes[nameof(s.GeometryLayer)].Text.Trim();s.AttributeLayer=boxes[nameof(s.AttributeLayer)].Text.Trim();s.LsePartAttribute=boxes[nameof(s.LsePartAttribute)].Text.Trim().ToUpperInvariant();if(s.LsePartAttribute.Length==0)throw new InvalidOperationException("LSE part attribute cannot be blank.");
  s.TagTextHeight=ParseDouble(boxes[nameof(s.TagTextHeight)].Text,"Tag text height");s.CurveTolerance=ParseDouble(boxes[nameof(s.CurveTolerance)].Text,"Curve tolerance");s.MaxCurves=int.TryParse(boxes[nameof(s.MaxCurves)].Text,out int m)&&m>0?m:throw new InvalidOperationException("Max curve segments must be a positive whole number.");
  s.ConvertToDwgWithAutoCad=checks[nameof(s.ConvertToDwgWithAutoCad)].Checked;s.AppendMpnToDescription=checks[nameof(s.AppendMpnToDescription)].Checked;s.VaultExplorerPath=boxes[nameof(s.VaultExplorerPath)].Text.Trim();s.VaultServer=boxes[nameof(s.VaultServer)].Text.Trim();s.VaultName=boxes[nameof(s.VaultName)].Text.Trim();s.CatalogVaultPath=boxes[nameof(s.CatalogVaultPath)].Text.Trim();SettingsService.Save(s);DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Settings",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 void Test(){var x=new List<string>();string cat=boxes[nameof(s.CatalogPath)].Text.Trim(),fp=boxes[nameof(s.FootprintLookupPath)].Text.Trim(),ns=boxes[nameof(s.NamingStandardPath)].Text.Trim();try{x.Add($"Catalog read: PASS ({new AccessCatalogService(cat).GetTables().Count} family tables)");}catch(Exception ex){x.Add("Catalog read: FAIL "+ex.Message);}try{new FootprintLookupService(fp).TableExists("AB");x.Add("Footprint lookup read: PASS");}catch(Exception ex){x.Add("Footprint lookup read: FAIL "+ex.Message);}try{var n=NamingStandardService.Load(ns);x.Add($"Naming standard: PASS ({n.Tabs.Count} tabs, {n.Manufacturers.Count} manufacturer codes; {n.Source})");}catch(Exception ex){x.Add("Naming standard: FAIL "+ex.Message);}x.Add("AutoCAD COM registered on this PC: "+(AutoCadConvertService.IsInstalled()?"yes":"no"));try{var t=new AppSettings{VaultExplorerPath=boxes[nameof(s.VaultExplorerPath)].Text.Trim(),VaultServer=boxes[nameof(s.VaultServer)].Text.Trim(),VaultName=boxes[nameof(s.VaultName)].Text.Trim(),CatalogVaultPath=boxes[nameof(s.CatalogVaultPath)].Text.Trim(),CatalogPath=cat};x.Add(VaultCatalogService.TestReport(t));}catch(Exception ex){x.Add("Vault test: FAIL "+ex.Message);}MessageBox.Show(this,string.Join(Environment.NewLine,x),"Settings test");}
 static string Inv(double v)=>v.ToString(System.Globalization.CultureInfo.InvariantCulture);
 static double ParseDouble(string t,string name)=>double.TryParse(t,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out double v)&&v>0?v:throw new InvalidOperationException(name+" must be a positive number.");
}
